         break;
      case "强健之术":
         this.role.skillLife = 10 * this.role.rateLife * levels;
         break;
      case "智慧之术":
         this.role.skillMp = 10 * this.role.rateMp * levels;
         break;
      case "英勇":
         this.role.skillAddFire = 5 * levels;
         break;
      default:
         return false;
   }
   this.role.flashAttribute();
   return true;
}
